override_bodies.parameterHandler:
def parameterHandler(self, params):
    import threading
    import moen_shower
    new = {}
    try:
        new['email'] = str((params or {}).get('email') or '').strip()
        new['password'] = str((params or {}).get('password') or '')
    except Exception:
        new = {'email': '', 'password': ''}
    old = getattr(self, 'moen_params', None)
    self.moen_params = new
    if getattr(self, 'moen_started', False) and old != new:
        threading.Thread(target=moen_shower.connect, args=(self,), daemon=True).start()

override_bodies.shortPoll:
def shortPoll(self, *args, **kwargs):
    import moen_shower
    moen_shower.refresh_all(self, False)

override_bodies.longPoll:
def longPoll(self, *args, **kwargs):
    import moen_shower
    nodes = getattr(self, 'moen_nodes', None)
    if not nodes:
        if getattr(self, 'moen_started', False) and not getattr(self, 'moen_auth_failed', False):
            moen_shower.connect(self)
        return
    moen_shower.refresh_all(self, True)

node_classes.moen_client:
"""Minimal U by Moen cloud client (REST + Pusher) used by the UByMoen plugin.

Moen publishes no official API. Endpoints and message shapes follow the
MIT-licensed community project https://github.com/WeaveHubHQ/ha-u-by-moen
(Jason Lazerus). Credentials and tokens are never logged.

Implementation note: this file deliberately contains no ``class`` statements.
The plugin scaffold treats every class in a node-class file as a device node,
so the helper classes (exceptions, MoenClient, _PusherConn) are assembled with
``type()`` from the plain functions registered below. Behaviour is the same as
ordinary classes.
"""
import json
import logging
import random
import threading
import time

import requests
import websocket

try:
    from udi_interface import LOGGER
except Exception:  # pragma: no cover - tests run without udi_interface logging
    LOGGER = logging.getLogger("ubymoen")

API_BASE = "https://www.moen-iot.com"
HTTP_TIMEOUT = 15
MIN_TEMP_F = 60
DEFAULT_MAX_TEMP_F = 115

MODE_INDEX = {"off": 0, "adjusting": 1, "ready": 2, "pause": 3, "paused-by-preset": 4}
POWER_ON_MODES = ("adjusting", "ready", "pause")

VOLATILE_FIELDS = frozenset(
    {
        "mode",
        "current_temperature",
        "target_temperature",
        "outlets",
        "active_preset",
        "timer_enabled",
        "time_remaining",
    }
)
REST_STATE_KEYS = (
    "mode",
    "current_temperature",
    "target_temperature",
    "max_temp",
    "outlets",
    "active_preset",
    "presets",
    "time_remaining",
    "timer_enabled",
    "timer_length",
    "name",
    "current_firmware_version",
)

# Exceptions (built with type(); see module docstring)
MoenError = type("MoenError", (Exception,), {"__doc__": "Any U by Moen API / transport / command problem."})
MoenAuthError = type("MoenAuthError", (MoenError,), {"__doc__": "Login was rejected."})
MoenHttpError = type("MoenHttpError", (MoenError,), {"__doc__": "HTTP error status from the Moen API.", "status": 0})


def _http_error(method, path, status):
    err = MoenHttpError("U by Moen %s %s returned HTTP %d" % (method.upper(), path, status))
    err.status = status
    return err


# ---------------------------------------------------------------- helpers

def mode_to_index(mode):
    return MODE_INDEX.get(mode)


def is_powered_on(mode):
    return mode in POWER_ON_MODES


def control_payload(action, params=None):
    data = {"action": action}
    if params is not None:
        data["params"] = params
    return {"type": "control", "data": data}


def power_payload(turn_on):
    if turn_on:
        return control_payload("shower_on", {})
    return control_payload("shower_off")


def temperature_payload(temperature, minimum, maximum):
    if isinstance(temperature, bool) or not isinstance(temperature, (int, float)):
        raise MoenError("Temperature must be numeric")
    if not (temperature == temperature) or not minimum <= temperature <= maximum:
        raise MoenError("Temperature must be between %g and %g" % (minimum, maximum))
    target = int(round(temperature))
    return control_payload("temperature_set", {"target_temperature": target}), target


def outlet_payload(outlets, position, active):
    if not outlets or any(
        not isinstance(o, dict)
        or not isinstance(o.get("position"), int)
        or not isinstance(o.get("active"), bool)
        for o in outlets
    ):
        raise MoenError("Current outlet state is incomplete")
    found = False
    updated = []
    for outlet in outlets:
        item = dict(outlet)
        if item["position"] == position:
            item["active"] = active
            found = True
        updated.append(item)
    if not found:
        raise MoenError("Outlet %s is not available" % position)
    return control_payload("outlets_set", {"outlets": updated}), updated


def preset_payload(presets, position):
    preset = next((p for p in presets if isinstance(p, dict) and p.get("position") == position), None)
    if preset is None:
        raise MoenError("Preset %s is not available" % position)
    if position <= 2:
        return control_payload("shower_on", {"preset": position}), dict(preset)
    return control_payload("shower_set", dict(preset)), dict(preset)


def _decode(value):
    if isinstance(value, str):
        try:
            return json.loads(value)
        except ValueError:
            return value
    return value


def parse_state_event(payload):
    """Normalize a client-state-reported payload -> (event_type, update dict)."""
    envelope = _decode(payload)
    if not isinstance(envelope, dict):
        return None, {}
    event_type = envelope.get("type")
    body = _decode(envelope.get("data", {}))
    if not isinstance(body, dict):
        body = {}
    aliases = {
        "current_mode": "mode",
        "current_temperature": "current_temperature",
        "target_temperature": "target_temperature",
        "outlets": "outlets",
        "active_preset": "active_preset",
        "timer_enabled": "timer_enabled",
        "time_remaining": "time_remaining",
        "presets": "presets",
        "timer_length": "timer_length",
    }
    update = {}
    for source, target in aliases.items():
        if source in body:
            update[target] = body[source]
    if "current_firmware_version" in envelope:
        update["current_firmware_version"] = envelope["current_firmware_version"]
    return (event_type if isinstance(event_type, str) else None), update


def merge_state(existing, update):
    """Merge a partial update, keeping per-outlet metadata."""
    merged = dict(existing)
    for key, value in update.items():
        if key == "outlets" and isinstance(value, list):
            by_pos = {
                o.get("position"): dict(o)
                for o in existing.get("outlets", [])
                if isinstance(o, dict) and o.get("position") is not None
            }
            result = []
            for item in value:
                if not isinstance(item, dict):
                    continue
                combined = dict(by_pos.get(item.get("position"), {}))
                combined.update(item)
                result.append(combined)
            merged[key] = result
        else:
            merged[key] = value
    return merged


def rest_to_state(details):
    return {k: details[k] for k in REST_STATE_KEYS if k in details}


# ------------------------------------------------- method registries

def _registry(store):
    def decorator(func):
        store[func.__name__] = func
        return func
    return decorator


_CLIENT_METHODS = {"__doc__": "REST login/discovery plus live Pusher control for the account's showers."}
_CONN_METHODS = {"__doc__": "One supervised Pusher WebSocket (runs in its own daemon thread)."}
_client_method = _registry(_CLIENT_METHODS)
_conn_method = _registry(_CONN_METHODS)


# ---------------------------------------------------------- MoenClient

@_client_method
def __init__(self, email, password, state_callback):
    self._email = email
    self._password = password
    self._state_cb = state_callback
    self._token = None
    self._lock = threading.RLock()
    self._http = requests.Session()
    self._conns = {}
    self._serial_conn = {}


@_client_method
def authenticate(self):
    with self._lock:
        try:
            resp = self._http.get(
                API_BASE + "/v2/authenticate",
                params={"email": self._email, "password": self._password},
                timeout=HTTP_TIMEOUT,
            )
        except requests.RequestException as err:
            raise MoenError("Authentication request failed (%s)" % type(err).__name__) from None
        if resp.status_code in (401, 403):
            raise MoenAuthError("Invalid U by Moen credentials")
        if resp.status_code >= 400:
            raise MoenError("Authentication returned HTTP %d" % resp.status_code)
        try:
            data = resp.json()
        except ValueError:
            raise MoenError("Authentication response was not JSON") from None
        token = data.get("token") if isinstance(data, dict) else None
        if not isinstance(token, str) or not token:
            raise MoenAuthError("Authentication response did not contain a token")
        self._token = token
        return token


@_client_method
def _ensure_token(self):
    with self._lock:
        if self._token is None:
            return self.authenticate()
        return self._token


@_client_method
def _request(self, method, path, headers=None, params=None, data=None,
             user_token_header=True, retry_auth=True, allow_empty=False):
    token = self._ensure_token()
    hdrs = dict(headers or {})
    if user_token_header and "User-Token" not in hdrs:
        hdrs["User-Token"] = token
    try:
        resp = self._http.request(
            method, API_BASE + path, headers=hdrs, params=params, data=data,
            timeout=HTTP_TIMEOUT,
        )
    except requests.RequestException as err:
        raise MoenError("U by Moen %s %s failed (%s)" % (method.upper(), path, type(err).__name__)) from None
    if resp.status_code == 401 and retry_auth:
        with self._lock:
            self._token = None
        fresh = self.authenticate()
        new_params = dict(params) if params is not None else None
        new_data = dict(data) if data is not None else None
        if new_params is not None and "user_token" in new_params:
            new_params["user_token"] = fresh
        if new_data is not None and "user_token" in new_data:
            new_data["user_token"] = fresh
        return self._request(method, path, headers=headers, params=new_params, data=new_data,
                             user_token_header=user_token_header, retry_auth=False,
                             allow_empty=allow_empty)
    if resp.status_code in (401, 403):
        raise MoenAuthError("U by Moen %s %s was not authorized" % (method.upper(), path))
    if resp.status_code >= 400:
        raise _http_error(method, path, resp.status_code)
    if resp.status_code == 204 or allow_empty or not resp.content:
        return None
    try:
        return resp.json()
    except ValueError:
        raise MoenError("U by Moen %s %s returned invalid JSON" % (method.upper(), path)) from None


@_client_method
def get_devices(self):
    devices = self._request("GET", "/v2/showers")
    if not isinstance(devices, list):
        raise MoenError("Showers response was not a list")
    return devices


@_client_method
def get_details(self, serial):
    details = self._request("GET", "/v5/showers/%s" % serial)
    if not isinstance(details, dict):
        raise MoenError("Shower detail response was not an object")
    return details


@_client_method
def _get_pusher_credentials(self, serial):
    token = self._ensure_token()
    try:
        creds = self._request(
            "GET", "/v2/credentials", user_token_header=False,
            params={"user_token": token, "serial_number": serial},
        )
        version = 2
    except MoenHttpError as err:
        if err.status not in (404, 405):
            raise MoenError("Failed to get Pusher credentials") from None
        creds = self._request("GET", "/v3/credentials")
        version = 3
    if not isinstance(creds, dict) or not creds.get("app_key") or not creds.get("cluster"):
        raise MoenError("Pusher credentials were incomplete")
    out = dict(creds)
    out["auth_version"] = version
    return out


@_client_method
def get_pusher_auth(self, channel, socket_id, serial, auth_version):
    token = self._ensure_token()
    form = {"channel_name": channel, "socket_id": socket_id}
    headers = {"Content-Type": "application/x-www-form-urlencoded"}
    if auth_version == 2:
        form["user_token"] = token
        form["serial_number"] = serial
        result = self._request("POST", "/v2/pusher-auth", headers=headers, data=form,
                               user_token_header=False)
    else:
        result = self._request("POST", "/v3/pusher-auth", headers=headers, data=form)
    auth = result.get("auth") if isinstance(result, dict) else None
    if not isinstance(auth, str) or not auth:
        raise MoenError("Pusher authorization response was incomplete")
    return auth


@_client_method
def _ensure_mobile_capability(self, details):
    caps = {c.get("name") for c in details.get("capabilities", []) if isinstance(c, dict)}
    if "pusher_hmi" not in caps or "mobile_supports_pusher" in caps:
        return
    shower_token = details.get("token")
    if not shower_token:
        return
    try:
        self._request(
            "POST", "/v2/capabilities", headers={"Shower-Token": shower_token},
            params={"name": "mobile_supports_pusher"}, user_token_header=False,
            allow_empty=True,
        )
    except MoenError as err:
        LOGGER.debug("Could not register mobile Pusher capability: %s", err)


@_client_method
def register_device(self, details):
    serial = details.get("serial_number")
    if not serial:
        raise MoenError("Device detail omitted serial_number")
    self._ensure_mobile_capability(details)
    creds = self._get_pusher_credentials(serial)
    channel_id = creds.get("channel") or details.get("channel")
    if not channel_id:
        raise MoenError("Pusher credentials omitted channel")
    channel = str(channel_id)
    if not channel.startswith("private-"):
        channel = "private-" + channel
    key = (str(creds["app_key"]), str(creds["cluster"]))
    with self._lock:
        conn = self._conns.get(key)
        if conn is None:
            conn = _PusherConn(self, key[0], key[1])
            self._conns[key] = conn
        conn.add_sub(serial, channel, int(creds.get("auth_version", 3)))
        self._serial_conn[serial] = conn


@_client_method
def start_pusher(self):
    for conn in list(self._conns.values()):
        conn.start()


@_client_method
def stop(self):
    for conn in list(self._conns.values()):
        conn.stop()
    self._conns = {}
    self._serial_conn = {}
    try:
        self._http.close()
    except Exception:
        pass


@_client_method
def is_healthy(self, serial):
    conn = self._serial_conn.get(serial)
    return conn is not None and conn.is_healthy(serial)


@_client_method
def request_report(self, serial):
    conn = self._serial_conn.get(serial)
    if conn is None:
        raise MoenError("No Pusher connection for %s" % serial)
    conn.request_report(serial)


@_client_method
def send_control(self, serial, payload):
    conn = self._serial_conn.get(serial)
    if conn is None:
        raise MoenError("No Pusher connection for %s" % serial)
    conn.send_event(serial, "client-state-desired", payload)


@_client_method
def _on_event(self, serial, event, payload):
    if event != "client-state-reported":
        return
    event_type, update = parse_state_event(payload)
    if event_type == "boot":
        try:
            self.request_report(serial)
        except MoenError as err:
            LOGGER.debug("Could not request report after boot: %s", err)
        return
    if event_type in ("state_change", "shower_report") and update:
        try:
            self._state_cb(serial, update)
        except Exception as err:  # keep the transport thread alive
            LOGGER.error("State callback failed: %s", err)


# --------------------------------------------------------- _PusherConn

@_conn_method
def __init__(self, client, app_key, cluster):
    self.client = client
    self.app_key = app_key
    self.cluster = cluster
    self.subs = {}
    self.ws = None
    self.socket_id = None
    self.thread = None
    self.running = False
    self.send_lock = threading.Lock()
    self.report_id = 0


@_conn_method
def add_sub(self, serial, channel, auth_version):
    self.subs[channel] = {
        "serial": serial,
        "channel": channel,
        "auth_version": auth_version,
        "ready": threading.Event(),
    }


@_conn_method
def is_healthy(self, serial):
    return any(s["serial"] == serial and s["ready"].is_set() for s in self.subs.values())


@_conn_method
def start(self):
    if self.thread is not None and self.thread.is_alive():
        return
    self.running = True
    self.thread = threading.Thread(target=self._supervise, name="moen-pusher", daemon=True)
    self.thread.start()


@_conn_method
def stop(self):
    self.running = False
    ws = self.ws
    if ws is not None:
        try:
            ws.close()
        except Exception:
            pass
    th = self.thread
    if th is not None and th is not threading.current_thread():
        th.join(5)
    self.thread = None
    self._mark_disconnected()


@_conn_method
def _mark_disconnected(self):
    self.socket_id = None
    for sub in self.subs.values():
        sub["ready"].clear()


@_conn_method
def _supervise(self):
    attempt = 0
    while self.running:
        established = False
        try:
            self._run_connection()
        except Exception as err:
            if self.running:
                LOGGER.warning("Pusher connection lost: %s", type(err).__name__)
        finally:
            established = self.socket_id is not None
            self._mark_disconnected()
            ws = self.ws
            self.ws = None
            if ws is not None:
                try:
                    ws.close()
                except Exception:
                    pass
        if not self.running:
            break
        attempt = 1 if established else attempt + 1
        delay = min(30.0, float(attempt * attempt)) + random.uniform(0, 1)
        end = time.time() + delay
        while self.running and time.time() < end:
            time.sleep(0.5)


@_conn_method
def _run_connection(self):
    url = "wss://ws-%s.pusher.com/app/%s?protocol=7&client=python-client&version=1.0" % (
        self.cluster, self.app_key)
    ws = websocket.create_connection(url, timeout=10)
    self.ws = ws
    activity_timeout = 120.0
    last_activity = time.monotonic()
    ping_sent = None
    while self.running:
        if ping_sent is None:
            wait = activity_timeout - (time.monotonic() - last_activity)
        else:
            wait = 30.0 - (time.monotonic() - ping_sent)
        if wait <= 0:
            if ping_sent is not None:
                raise MoenError("Timed out waiting for Pusher pong")
            self._send({"event": "pusher:ping"})
            ping_sent = time.monotonic()
            continue
        ws.settimeout(max(0.5, min(wait, 5.0)))
        try:
            raw = ws.recv()
        except websocket.WebSocketTimeoutException:
            continue
        if not raw:
            raise MoenError("Pusher WebSocket closed")
        last_activity = time.monotonic()
        ping_sent = None
        negotiated = self._handle(raw)
        if negotiated:
            activity_timeout = negotiated


@_conn_method
def _handle(self, raw):
    try:
        msg = json.loads(raw)
    except (TypeError, ValueError):
        return None
    if not isinstance(msg, dict):
        return None
    event = msg.get("event")
    data = msg.get("data")
    if event == "pusher:connection_established":
        info = _decode(data)
        if not isinstance(info, dict) or not info.get("socket_id"):
            raise MoenError("Pusher connection omitted socket_id")
        self.socket_id = str(info["socket_id"])
        for sub in list(self.subs.values()):
            self._subscribe(sub)
        timeout = info.get("activity_timeout")
        if isinstance(timeout, (int, float)) and not isinstance(timeout, bool):
            return max(1.0, float(timeout))
    elif event == "pusher:ping":
        self._send({"event": "pusher:pong"})
    elif event == "pusher:error":
        raise MoenError("Pusher returned an error")
    elif event == "pusher_internal:subscription_succeeded":
        sub = self.subs.get(msg.get("channel"))
        if sub is not None:
            sub["ready"].set()
            LOGGER.info("Subscribed to live U by Moen updates for %s", sub["serial"])
            self.request_report(sub["serial"])
    elif isinstance(event, str):
        sub = self.subs.get(msg.get("channel"))
        if sub is not None:
            self.client._on_event(sub["serial"], event, _decode(data))
    return None


@_conn_method
def _subscribe(self, sub):
    if self.socket_id is None:
        raise MoenError("Pusher socket is not established")
    auth = self.client.get_pusher_auth(
        sub["channel"], self.socket_id, sub["serial"], sub["auth_version"])
    self._send({"event": "pusher:subscribe", "data": {"channel": sub["channel"], "auth": auth}})


@_conn_method
def _send(self, message):
    ws = self.ws
    if ws is None:
        raise MoenError("Pusher WebSocket is disconnected")
    with self.send_lock:
        try:
            ws.send(json.dumps(message, separators=(",", ":")))
        except (websocket.WebSocketException, OSError) as err:
            raise MoenError("Pusher send failed (%s)" % type(err).__name__) from None


@_conn_method
def _find(self, serial):
    for sub in self.subs.values():
        if sub["serial"] == serial:
            return sub
    raise MoenError("No Pusher channel for %s" % serial)


@_conn_method
def request_report(self, serial):
    sub = self._find(serial)
    if not sub["ready"].is_set():
        raise MoenError("Pusher channel is not subscribed")
    self.report_id = (self.report_id + 1) % 1000
    payload = {"jsonrpc": "2.0", "method": "do_shower_report", "id": self.report_id}
    self._send({
        "event": "client-command",
        "channel": sub["channel"],
        "data": json.dumps(payload, separators=(",", ":")),
    })


@_conn_method
def send_event(self, serial, event, payload, timeout=10.0):
    sub = self._find(serial)
    if not sub["ready"].wait(timeout):
        raise MoenError("Pusher channel did not become ready")
    self._send({
        "event": event,
        "channel": sub["channel"],
        "data": json.dumps(payload, separators=(",", ":")),
    })


MoenClient = type("MoenClient", (), dict(_CLIENT_METHODS))
_PusherConn = type("_PusherConn", (), dict(_CONN_METHODS))

node_classes.moen_shower:
"""Shower node and connection orchestration for the UByMoen plugin."""
import threading

import udi_interface

from moen_client import (
    DEFAULT_MAX_TEMP_F,
    MIN_TEMP_F,
    VOLATILE_FIELDS,
    MoenAuthError,
    MoenClient,
    MoenError,
    is_powered_on,
    merge_state,
    mode_to_index,
    outlet_payload,
    power_payload,
    preset_payload,
    rest_to_state,
    temperature_payload,
)

Node = udi_interface.Node
LOGGER = udi_interface.LOGGER

MAX_PRESET_POSITION = 10


class ShowerNode(Node):
    id = "shower"
    drivers = [
        {'driver': 'ST', 'value': 0, 'uom': 25, 'name': 'Shower Power'},
        {'driver': 'CLITEMP', 'value': 0, 'uom': 17, 'name': 'Current Temperature'},
        {'driver': 'CLISPH', 'value': 0, 'uom': 17, 'name': 'Target Temperature'},
        {'driver': 'MODE', 'value': 0, 'uom': 25, 'name': 'Mode'},
        {'driver': 'PRESET', 'value': 0, 'uom': 25, 'name': 'Active Preset'},
        {'driver': 'TIMEREM', 'value': 0, 'uom': 58, 'name': 'Time Remaining'},
        {'driver': 'OUTLET1', 'value': 0, 'uom': 25, 'name': 'Outlet 1'},
        {'driver': 'OUTLET2', 'value': 0, 'uom': 25, 'name': 'Outlet 2'},
        {'driver': 'OUTLET3', 'value': 0, 'uom': 25, 'name': 'Outlet 3'},
        {'driver': 'OUTLET4', 'value': 0, 'uom': 25, 'name': 'Outlet 4'},
    ]

    def __init__(self, polyglot, primary, address, name, serial, moen):
        super().__init__(polyglot, primary, address, name)
        self.moen_serial = serial
        self.moen = moen
        self.shower_state = {}
        self._state_lock = threading.RLock()
        self._preset_sig = None

    # ------------------------------------------------------------ state
    def apply_state(self, update):
        if not update:
            return
        with self._state_lock:
            self.shower_state = merge_state(self.shower_state, update)
            snapshot = dict(self.shower_state)
        try:
            self._publish(snapshot)
        except Exception as err:
            LOGGER.error('Could not publish shower state: %s', err)

    @staticmethod
    def _sorted_outlets(state):
        outlets = state.get('outlets')
        if not isinstance(outlets, list):
            return []
        good = [o for o in outlets if isinstance(o, dict) and isinstance(o.get('position'), int)]
        return sorted(good, key=lambda o: o['position'])

    def _set_temp(self, driver, value):
        if isinstance(value, (int, float)) and not isinstance(value, bool):
            self.setDriver(driver, int(round(value)))

    def _set_preset_driver(self, position, title):
        try:
            self.setDriver('PRESET', position, text=title)
        except TypeError:
            self.setDriver('PRESET', position)

    def _publish(self, st):
        mode = st.get('mode')
        index = mode_to_index(mode)
        if index is not None:
            self.setDriver('MODE', index)
            self.setDriver('ST', 1 if is_powered_on(mode) else 0)
        elif mode is not None:
            LOGGER.warning('Unknown shower mode %r', mode)
        self._set_temp('CLITEMP', st.get('current_temperature'))
        self._set_temp('CLISPH', st.get('target_temperature'))

        presets = st.get('presets')
        if isinstance(presets, list):
            self._update_preset_editors(presets)
        active = st.get('active_preset')
        position = active if isinstance(active, int) and not isinstance(active, bool) else 0
        title = 'None'
        if position and isinstance(presets, list):
            match = next((p for p in presets if isinstance(p, dict) and p.get('position') == position), None)
            title = str((match or {}).get('title') or 'Preset %d' % position)
        self._set_preset_driver(position, title)

        remaining = st.get('time_remaining')
        if isinstance(remaining, (int, float)) and not isinstance(remaining, bool):
            self.setDriver('TIMEREM', int(remaining))
        elif 'time_remaining' in st and remaining is None:
            self.setDriver('TIMEREM', 0)

        for i, outlet in enumerate(self._sorted_outlets(st)[:4]):
            self.setDriver('OUTLET%d' % (i + 1), 1 if outlet.get('active') else 0)

    def _update_preset_editors(self, presets):
        names = {}
        for item in presets:
            if not isinstance(item, dict):
                continue
            pos = item.get('position')
            if isinstance(pos, int) and 1 <= pos <= MAX_PRESET_POSITION:
                names[pos] = str(item.get('title') or 'Preset %d' % pos)
        if not names:
            return
        signature = tuple(sorted(names.items()))
        if signature == self._preset_sig:
            return
        self._preset_sig = signature
        positions = sorted(names)
        pick_subset = ','.join(str(p) for p in positions)
        status_names = {'0': 'None'}
        status_names.update({str(p): names[p] for p in positions})
        editors = [
            {'id': 'shower_preset', 'ranges': [
                {'uom': '25', 'subset': '0,' + pick_subset, 'names': status_names}]},
            {'id': 'shower_preset_pick', 'ranges': [
                {'uom': '25', 'subset': pick_subset,
                 'names': {str(p): names[p] for p in positions}}]},
        ]
        threading.Thread(target=self._push_profile, args=(editors,), daemon=True).start()

    def _push_profile(self, editors):
        try:
            self.poly.updateJsonProfile({'editors': editors}, {'waitResponse': True})
        except Exception as err:
            LOGGER.warning('Could not update preset names: %s', err)

    # --------------------------------------------------------- commands
    @staticmethod
    def _command_value(command):
        if isinstance(command, dict):
            value = command.get('value')
            if value is None and isinstance(command.get('query'), dict):
                for candidate in command['query'].values():
                    return candidate
            return value
        return command

    @staticmethod
    def _parse_bool(value):
        text = str(value).strip().lower()
        if text in ('1', '1.0', 'true', 'on', '100'):
            return True
        if text in ('0', '0.0', 'false', 'off'):
            return False
        return None

    def _request_report_later(self):
        try:
            self.moen.request_report(self.moen_serial)
        except MoenError as err:
            LOGGER.debug('Report request failed: %s', err)

    def _send(self, payload, optimistic=None):
        try:
            self.moen.send_control(self.moen_serial, payload)
        except MoenError as err:
            LOGGER.error('Shower command failed: %s', err)
            return False
        if optimistic:
            self.apply_state(optimistic)
        timer = threading.Timer(3.0, self._request_report_later)
        timer.daemon = True
        timer.start()
        return True

    def shower_on(self, command=None, *args, **kwargs):
        self._send(power_payload(True), {'mode': 'adjusting'})

    def shower_off(self, command=None, *args, **kwargs):
        self._send(power_payload(False), {'mode': 'off'})

    def set_temp(self, command=None, *args, **kwargs):
        try:
            temperature = float(self._command_value(command))
        except (TypeError, ValueError):
            LOGGER.error('Set Temperature needs a numeric value')
            return
        with self._state_lock:
            max_temp = self.shower_state.get('max_temp')
        try:
            maximum = float(max_temp) if max_temp else float(DEFAULT_MAX_TEMP_F)
        except (TypeError, ValueError):
            maximum = float(DEFAULT_MAX_TEMP_F)
        try:
            payload, target = temperature_payload(temperature, MIN_TEMP_F, maximum)
        except MoenError as err:
            LOGGER.error('Set Temperature rejected: %s', err)
            return
        self._send(payload, {'target_temperature': target})

    def start_preset(self, command=None, *args, **kwargs):
        try:
            position = int(float(self._command_value(command)))
        except (TypeError, ValueError):
            LOGGER.error('Start Preset needs a preset number')
            return
        with self._state_lock:
            presets = list(self.shower_state.get('presets') or [])
        try:
            payload, preset = preset_payload(presets, position)
        except MoenError as err:
            LOGGER.error('Start Preset rejected: %s', err)
            return
        optimistic = {'active_preset': position, 'mode': 'adjusting'}
        if isinstance(preset.get('target_temperature'), (int, float)):
            optimistic['target_temperature'] = preset['target_temperature']
        self._send(payload, optimistic)

    def _set_outlet(self, command, index):
        active = self._parse_bool(self._command_value(command))
        if active is None:
            LOGGER.error('Outlet %d needs an On/Off value', index + 1)
            return
        with self._state_lock:
            snapshot = dict(self.shower_state)
        sorted_outlets = self._sorted_outlets(snapshot)
        if index >= len(sorted_outlets):
            LOGGER.error('Outlet %d is not available on this shower', index + 1)
            return
        position = sorted_outlets[index]['position']
        try:
            payload, updated = outlet_payload(snapshot.get('outlets') or [], position, active)
        except MoenError as err:
            LOGGER.error('Outlet %d rejected: %s', index + 1, err)
            return
        self._send(payload, {'outlets': updated})

    def outlet1(self, command=None, *args, **kwargs):
        self._set_outlet(command, 0)

    def outlet2(self, command=None, *args, **kwargs):
        self._set_outlet(command, 1)

    def outlet3(self, command=None, *args, **kwargs):
        self._set_outlet(command, 2)

    def outlet4(self, command=None, *args, **kwargs):
        self._set_outlet(command, 3)

    def query_cmd(self, command=None, *args, **kwargs):
        self._request_report_later()
        self.reportDrivers()

    commands = {
        'DON': shower_on,
        'DOF': shower_off,
        'SET_TEMP': set_temp,
        'START_PRESET': start_preset,
        'OUTLET1': outlet1,
        'OUTLET2': outlet2,
        'OUTLET3': outlet3,
        'OUTLET4': outlet4,
        'QUERY': query_cmd,
    }


# ------------------------------------------------- connection management

_CONNECT_LOCK = threading.RLock()


def _notice(ctrl, key, text=None):
    try:
        if text:
            ctrl.poly.Notices[key] = text
        else:
            ctrl.poly.Notices.delete(key)
    except Exception:
        pass


def shutdown(ctrl):
    client = getattr(ctrl, 'moen', None)
    ctrl.moen = None
    ctrl.moen_nodes = {}
    if client is not None:
        try:
            client.stop()
        except Exception as err:
            LOGGER.debug('Error stopping Moen client: %s', err)


def connect(ctrl):
    """(Re)connect to the Moen cloud and (re)create shower nodes. Returns node count."""
    with _CONNECT_LOCK:
        ctrl.moen_auth_failed = False
        params = getattr(ctrl, 'moen_params', None) or {}
        email = str(params.get('email') or '').strip()
        password = str(params.get('password') or '')
        if not email or not password:
            _notice(ctrl, 'moen_cfg', 'Enter your U by Moen email and password in the plugin configuration.')
            return 0
        _notice(ctrl, 'moen_cfg')
        shutdown(ctrl)

        nodes = {}

        def on_state(serial, update):
            node = nodes.get(serial)
            if node is not None:
                node.apply_state(update)

        client = MoenClient(email, password, on_state)
        try:
            client.authenticate()
            devices = client.get_devices()
        except MoenAuthError:
            ctrl.moen_auth_failed = True
            _notice(ctrl, 'moen_auth', 'U by Moen login failed. Check the email/password (an Alexa/Android account is required).')
            client.stop()
            return 0
        except MoenError as err:
            LOGGER.error('Could not reach U by Moen: %s', err)
            _notice(ctrl, 'moen_net', 'Could not reach the U by Moen cloud. Will retry automatically.')
            client.stop()
            return 0
        _notice(ctrl, 'moen_auth')
        _notice(ctrl, 'moen_net')

        for device in devices:
            serial = device.get('serial_number') if isinstance(device, dict) else None
            if not serial:
                continue
            try:
                details = client.get_details(serial)
            except MoenError as err:
                LOGGER.warning('Could not read details for %s: %s', serial, err)
                details = device
            address = ctrl.poly.getValidAddress('shower_' + str(serial)[-7:])
            name = ctrl.poly.getValidName(str(details.get('name') or 'Shower'))
            node = ShowerNode(ctrl.poly, ctrl.address, address, name, serial, client)
            ctrl.poly.addNode(node)
            nodes[serial] = node
            node.apply_state(rest_to_state(details))
            try:
                client.register_device(details)
            except MoenError as err:
                LOGGER.warning('Live updates unavailable for %s, using polling: %s', serial, err)

        ctrl.moen = client
        ctrl.moen_nodes = nodes
        client.start_pusher()
        if not nodes:
            _notice(ctrl, 'moen_none', 'No showers were found on this U by Moen account.')
        else:
            _notice(ctrl, 'moen_none')
        return len(nodes)


def refresh_all(ctrl, full):
    """REST refresh. full=False only refreshes showers whose live channel is down."""
    client = getattr(ctrl, 'moen', None)
    nodes = getattr(ctrl, 'moen_nodes', None) or {}
    if client is None:
        return
    for serial, node in list(nodes.items()):
        healthy = client.is_healthy(serial)
        if healthy and not full:
            continue
        try:
            details = client.get_details(serial)
        except MoenAuthError:
            ctrl.moen_auth_failed = True
            _notice(ctrl, 'moen_auth', 'U by Moen login failed. Check the email/password (an Alexa/Android account is required).')
            return
        except MoenError as err:
            LOGGER.warning('Refresh failed for %s: %s', serial, err)
            continue
        update = rest_to_state(details)
        if healthy:
            update = {k: v for k, v in update.items() if k not in VOLATILE_FIELDS}
        node.apply_state(update)
        if healthy:
            try:
                client.request_report(serial)
            except MoenError:
                pass
